std::string compress(const std::string& s) {
    std::string result;
    std::size_t i = 0;
    while (i < s.size()) {
        std::size_t j = i;
        while (j < s.size() && s[j] == s[i]) {
            j++;
        }
        result += s[i];
        if (j - i > 1) {
            result += std::to_string(j - i);
        }
        i = j;
    }
    return result;
}

int main() {
    std::string s;
    std::cin >> s;
    std::cout << compress(s) << "\n";
    return 0;
}

