package main

import (
	"fmt"
	"strconv"
	"strings"
)

func compress(s string) string {
	var b strings.Builder
	i := 0
	for i < len(s) {
		j := i
		for j < len(s) && s[j] == s[i] {
			j++
		}
		b.WriteByte(s[i])
		if j-i > 1 {
			b.WriteString(strconv.Itoa(j - i))
		}
		i = j
	}
	return b.String()
}

func main() {
	var s string
	fmt.Scan(&s)
	fmt.Println(compress(s))
}

