const input = readFileSync(0, "utf8");

function compress(s: string): string {
  const parts: string[] = [];
  let i = 0;
  while (i < s.length) {
    const letter = s.charAt(i);
    let j = i;
    while (j < s.length && s.charAt(j) === letter) {
      j++;
    }
    parts.push(j - i > 1 ? letter + String(j - i) : letter);
    i = j;
  }
  return parts.join("");
}

